## 1. Identification Strategy
- Method: Sharp Regression Discontinuity Design (RDD).
- Why: Eligibility for the merit scholarship turns on a hard GPA threshold. Comparing students just below and just above the cutoff identifies the local causal effect of scholarship eligibility on college enrollment.
- Key assumptions:
  - Continuity of potential outcomes at the GPA cutoff: in the absence of the scholarship rule, the conditional expectation of enrollment would evolve smoothly through the cutoff.
  - No precise manipulation of GPA around the threshold (i.e., density of the running variable is continuous at the cutoff).
  - Stable treatment rule (sharp assignment) at the cutoff.

## 2. R Code
```r
# Load packages (install if needed)
req_pkgs <- c("sandwich", "lmtest")
for (p in req_pkgs) {
  if (!requireNamespace(p, quietly = TRUE)) {
    install.packages(p, repos = "https://cloud.r-project.org")
  }
}
suppressPackageStartupMessages({
  library(sandwich)
  library(lmtest)
})

# Try to load optional packages for RD-specific utilities
opt_pkgs <- c("rddensity")
for (p in opt_pkgs) {
  if (!requireNamespace(p, quietly = TRUE)) {
    try(suppressWarnings(install.packages(p, repos = "https://cloud.r-project.org")), silent = TRUE)
  }
}

# Read data
path <- "experiments/exp_b/data/s85_data.csv"
dat <- read.csv(path)

# Basic cleaning
dat <- subset(dat, is.finite(running_var) & is.finite(y))
# Cutoff inferred from preview and treatment rule appears to be 0.5
c0 <- 0.5

# Local polynomial RD estimator (weighted WLS) with robust (HC1) SEs
local_rd <- function(data, c = 0.5, h = 0.1, p = 1, kernel = "triangular", donut = 0) {
  x <- data$running_var
  y <- data$y
  D <- as.integer(x >= c)
  xr <- x - c

  use <- (abs(xr) <= h)
  if (!is.null(donut) && donut > 0) {
    use <- use & (abs(xr) >= donut)
  }

  if (kernel == "triangular") {
    w <- pmax(0, 1 - abs(xr[use]) / h)
  } else if (kernel == "epanechnikov") {
    w <- 0.75 * pmax(0, 1 - (xr[use] / h)^2)
  } else {
    w <- rep(1, sum(use))
  }

  df <- data.frame(y = y[use], D = D[use], xr = xr[use])
  if (p == 1) {
    mod <- lm(y ~ D + xr + D:xr, data = df, weights = w)
    vc <- sandwich::vcovHC(mod, type = "HC1")
    est <- coef(mod)["D"]
    se  <- sqrt(diag(vc))["D"]
  } else if (p == 2) {
    df$xr2 <- df$xr^2
    mod <- lm(y ~ D + xr + I(xr^2) + D:xr + D:I(xr^2), data = df, weights = w)
    vc <- sandwich::vcovHC(mod, type = "HC1")
    est <- coef(mod)["D"]
    se  <- sqrt(diag(vc))["D"]
  } else {
    stop("Polynomial order p must be 1 or 2.")
  }

  nL <- sum(use & x < c)
  nR <- sum(use & x >= c)
  tval <- as.numeric(est / se)
  pval <- 2 * pnorm(-abs(tval))
  ci_lo <- as.numeric(est - 1.96 * se)
  ci_hi <- as.numeric(est + 1.96 * se)

  list(est = as.numeric(est),
       se = as.numeric(se),
       t = tval,
       p = pval,
       ci = c(ci_lo, ci_hi),
       nL = nL, nR = nR, h = h, p_order = p)
}

rp <- function(x, d = 3) format(round(x, d), nsmall = d, trim = TRUE)

# Main RD estimate: local linear, triangular kernel, bandwidth h = 0.10
res_main <- local_rd(dat, c = c0, h = 0.10, p = 1, kernel = "triangular", donut = 0)

cat("Main RD estimate (local linear, triangular kernel)\n")
cat("Cutoff c =", c0, " | Bandwidth h = ", rp(res_main$h, 2), " | nL = ", res_main$nL, " | nR = ", res_main$nR, "\n", sep = "")
cat("Effect on enrollment at cutoff (levels): ", rp(res_main$est, 4),
    "  SE: ", rp(res_main$se, 4),
    "  95% CI: [", rp(res_main$ci[1], 4), ", ", rp(res_main$ci[2], 4), "]",
    "  p-value: ", rp(res_main$p, 4), "\n", sep = "")
cat("Interpretation: effect in percentage points ≈ ", rp(100 * res_main$est, 2), " pp\n\n", sep = "")

# Robustness 1: Alternative bandwidths
for (h in c(0.05, 0.075, 0.15)) {
  r <- local_rd(dat, c = c0, h = h, p = 1, kernel = "triangular", donut = 0)
  cat("Bandwidth check h = ", rp(h, 3), ": est = ", rp(r$est, 4),
      " (SE ", rp(r$se, 4), ", p ", rp(r$p, 4), "); nL=", r$nL, ", nR=", r$nR, "\n", sep = "")
}
cat("\n")

# Robustness 2: Quadratic polynomial (p=2) within the main bandwidth
res_quad <- local_rd(dat, c = c0, h = 0.10, p = 2, kernel = "triangular", donut = 0)
cat("Polynomial order check (p=2, h=0.10): est = ", rp(res_quad$est, 4),
    " (SE ", rp(res_quad$se, 4), ", p ", rp(res_quad$p, 4), ")\n\n", sep = "")

# Robustness 3: Donut RDD (drop obs very close to cutoff, e.g., ±0.01)
res_donut <- local_rd(dat, c = c0, h = 0.10, p = 1, kernel = "triangular", donut = 0.01)
cat("Donut RD (exclude |GPA - cutoff| < 0.01): est = ", rp(res_donut$est, 4),
    " (SE ", rp(res_donut$se, 4), ", p ", rp(res_donut$p, 4), "); nL=", res_donut$nL, ", nR=", res_donut$nR, "\n\n", sep = "")

# Robustness 4: Simple "local randomization" diff-in-means using provided near_cutoff window
if ("near_cutoff" %in% names(dat)) {
  sub <- subset(dat, near_cutoff == 1)
  if (nrow(sub) >= 20) {
    sub$D <- as.integer(sub$running_var >= c0)
    m_lm <- lm(y ~ D, data = sub)
    vc_m <- sandwich::vcovHC(m_lm, type = "HC1")
    est_m <- coef(m_lm)["D"]
    se_m  <- sqrt(diag(vc_m))["D"]
    t_m <- est_m / se_m
    p_m <- 2 * pnorm(-abs(t_m))
    cat("Near-cutoff window diff-in-means (provided flag): est = ", rp(est_m, 4),
        " (SE ", rp(se_m, 4), ", p ", rp(p_m, 4), "); n = ", nrow(sub), "\n\n", sep = "")
  }
}

# Robustness 5: Placebo cutoffs
placebos <- c(0.40, 0.60)
for (cp in placebos) {
  rpl <- local_rd(dat, c = cp, h = 0.10, p = 1, kernel = "triangular", donut = 0)
  ok <- (rpl$nL >= 15 && rpl$nR >= 15)
  if (ok) {
    cat("Placebo cutoff c = ", rp(cp, 2), " (h=0.10): est = ", rp(rpl$est, 4),
        " (SE ", rp(rpl$se, 4), ", p ", rp(rpl$p, 4), "); nL=", rpl$nL, ", nR=", rpl$nR, "\n", sep = "")
  } else {
    cat("Placebo cutoff c = ", rp(cp, 2), ": insufficient data on one side (nL=", rpl$nL, ", nR=", rpl$nR, ")\n", sep = "")
  }
}
cat("\n")

# Manipulation (density) test at the cutoff (optional, if package available)
if (requireNamespace("rddensity", quietly = TRUE)) {
  suppressPackageStartupMessages(library(rddensity))
  den <- rddensity::rddensity(dat$running_var, c = c0)
  # Extract test results if available; otherwise, print a concise summary
  sden <- try(rddensity::summary.rddensity(den), silent = TRUE)
  cat("McCrary density continuity test at cutoff:\n")
  if (!inherits(sden, "try-error")) {
    # Attempt to extract the main z-stat and p-value from the summary object printing
    # If structure is unknown, print summary text
    print(sden)
  } else {
    print(den)
  }
} else {
  cat("Density test (rddensity) not available; skipped.\n")
}
```

## 3. Expected Findings
- Sign: Positive. Meeting the scholarship GPA threshold should increase the probability of enrolling in college due to reduced net price and salience of merit recognition.
- Magnitude: For students near the cutoff, a local average treatment effect on enrollment of roughly 5–12 percentage points is plausible. The exact point estimate will depend on the bandwidth and specification but should be robustly positive under valid RD assumptions.
